New task:
TASK AND SPECIFICATIONS
{
  "schema_version": 1,
  "id": "SELF005",
  "kind": "self_built",
  "title": "Three phase signal with externally clocked durations",
  "difficulty": "medium",
  "provenance": {
    "source_type": "independent_synthesis",
    "source_file": "scripts/build_self_dataset.py",
    "source_index": 5,
    "adaptation": "Independently specified for this project; no public task was copied. The coding assistant chose the state variables, priority order and fixed scan traces, then reviewed the traces against a separate Python transition implementation.",
    "rationale": "A training traffic signal uses a deterministic logical tick, allowing reproducible testing without wall-clock timing jitter.",
    "review": "Assistant consistency review of initialization, simultaneous commands, retained state and recovery boundaries; independent Python oracle checked against manual expected traces. Not an industrial safety certification or external expert review."
  },
  "requirements": "Phase 0 is RED for 2 Tick=TRUE invocations, phase 1 GREEN for 3, and phase 2 AMBER for 1. At initialization set phase RED and elapsed ticks zero. With Enable FALSE force RED and clear elapsed ticks every scan. With Enable TRUE and Tick FALSE retain phase and elapsed ticks. A TRUE Tick adds one; upon reaching that phase's duration transition RED->GREEN->AMBER->RED and clear elapsed ticks. Output Phase is 0,1,2 and exactly one color describes the post-transition phase. Tick is an enable level per invocation, not a rising-edge detector.",
  "scenario": "A training traffic signal uses a deterministic logical tick, allowing reproducible testing without wall-clock timing jitter.",
  "interface": [
    {
      "direction": "INPUT",
      "name": "Enable",
      "type": "BOOL",
      "description": "Enable normal signal cycle"
    },
    {
      "direction": "INPUT",
      "name": "Tick",
      "type": "BOOL",
      "description": "One logical tick on each TRUE invocation"
    },
    {
      "direction": "OUTPUT",
      "name": "Red",
      "type": "BOOL",
      "description": "Red lamp"
    },
    {
      "direction": "OUTPUT",
      "name": "Green",
      "type": "BOOL",
      "description": "Green lamp"
    },
    {
      "direction": "OUTPUT",
      "name": "Amber",
      "type": "BOOL",
      "description": "Amber lamp"
    },
    {
      "direction": "OUTPUT",
      "name": "Phase",
      "type": "USINT",
      "description": "Post-scan phase number"
    }
  ],
  "initial_conditions": {
    "phase": 0,
    "elapsed_ticks": 0
  },
  "scan_semantics": "At scan k, sample every input once, read retained pre-state q[k], execute one transition, and observe outputs O[k] at the end of that same scan. Updated state becomes q[k+1]. Reset the instance before each test. Step 0 executes normally; initial conditions describe pre-state, not an extra delayed scan. All timing in this task is explicitly counted in invocations, not wall time.",
  "safety_priority": [
    "Disable resets the cycle to RED"
  ],
  "assumptions": [
    "A logical tick is not claimed to be a physical second.",
    "No opposite road or pedestrian signal is controlled."
  ],
  "atomic_propositions": {
    "Enable": "Enable normal signal cycle Boolean names are propositions; numeric names appear only inside defined predicates.",
    "Tick": "One logical tick on each TRUE invocation Boolean names are propositions; numeric names appear only inside defined predicates.",
    "Red": "Red lamp Boolean names are propositions; numeric names appear only inside defined predicates.",
    "Green": "Green lamp Boolean names are propositions; numeric names appear only inside defined predicates.",
    "Amber": "Amber lamp Boolean names are propositions; numeric names appear only inside defined predicates.",
    "Phase": "Post-scan phase number Boolean names are propositions; numeric names appear only inside defined predicates.",
    "first": "True only on the first invocation after resetting the FB instance.",
    "qRedLast": "Pre-state is RED with one elapsed tick.",
    "qGreenLast": "Pre-state is GREEN with two elapsed ticks.",
    "qAmber": "Pre-state is AMBER.",
    "qPhase": "Pre-state phase number.",
    "oneColor": "Exactly one of Red, Green and Amber is TRUE."
  },
  "ltl": [
    {
      "id": "P1",
      "formula": "G(oneColor)",
      "explanation": "The lamp encoding is one-hot."
    },
    {
      "id": "P2",
      "formula": "G(!Enable -> (Red & !Green & !Amber))",
      "explanation": "Disabled operation is a steady red."
    },
    {
      "id": "P3",
      "formula": "G((Enable & !Tick) -> (Phase = qPhase))",
      "explanation": "No tick preserves phase."
    },
    {
      "id": "P4",
      "formula": "G((Enable & Tick & qRedLast) -> Green)",
      "explanation": "The second red tick enters green."
    },
    {
      "id": "P5",
      "formula": "G((Enable & Tick & qGreenLast) -> Amber)",
      "explanation": "The third green tick enters amber."
    },
    {
      "id": "P6",
      "formula": "G((Enable & Tick & qAmber) -> Red)",
      "explanation": "One amber tick returns red."
    },
    {
      "id": "P7",
      "formula": "(G Enable & G(F Tick)) -> (G(F Red) & G(F Green) & G(F Amber))",
      "explanation": "Persistent enable plus infinitely many ticks makes every phase recur; finite traces cannot prove this liveness property."
    }
  ],
  "tests": [
    {
      "id": "cycle",
      "purpose": "Full phase duration boundaries and pause",
      "steps": [
        {
          "inputs": {
            "Enable": true,
            "Tick": true
          },
          "expected": {
            "Phase": 0,
            "Red": true,
            "Green": false,
            "Amber": false
          }
        },
        {
          "inputs": {
            "Enable": true,
            "Tick": false
          },
          "expected": {
            "Phase": 0
          }
        },
        {
          "inputs": {
            "Enable": true,
            "Tick": true
          },
          "expected": {
            "Phase": 1
          }
        },
        {
          "inputs": {
            "Enable": true,
            "Tick": true
          },
          "expected": {
            "Phase": 1
          }
        },
        {
          "inputs": {
            "Enable": true,
            "Tick": true
          },
          "expected": {
            "Phase": 1
          }
        },
        {
          "inputs": {
            "Enable": true,
            "Tick": true
          },
          "expected": {
            "Phase": 2
          }
        },
        {
          "inputs": {
            "Enable": true,
            "Tick": true
          },
          "expected": {
            "Phase": 0
          }
        }
      ]
    },
    {
      "id": "disable",
      "purpose": "Disable clears elapsed tick progress",
      "steps": [
        {
          "inputs": {
            "Enable": true,
            "Tick": true
          },
          "expected": {
            "Phase": 0
          }
        },
        {
          "inputs": {
            "Enable": true,
            "Tick": true
          },
          "expected": {
            "Phase": 1
          }
        },
        {
          "inputs": {
            "Enable": false,
            "Tick": true
          },
          "expected": {
            "Phase": 0,
            "Red": true
          }
        },
        {
          "inputs": {
            "Enable": true,
            "Tick": true
          },
          "expected": {
            "Phase": 0
          }
        },
        {
          "inputs": {
            "Enable": true,
            "Tick": true
          },
          "expected": {
            "Phase": 1
          }
        }
      ]
    }
  ]
}
